use std::path::{Path,PathBuf};
use sha2::{Digest,Sha256};use tokio_util::sync::CancellationToken;
use video_kadr_backend::services::{concat_video_checkpoint::Expected,concat_video_analysis::{import_checkpoint,RunCache}};
fn digest(bytes:&[u8])->String{format!("{:x}",Sha256::digest(bytes))}
fn directory(path:&Path){std::fs::create_dir(path).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700)).unwrap();}}
fn file(path:&Path,bytes:&[u8]){std::fs::write(path,bytes).unwrap();#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o600)).unwrap();}}
const PERSON:&str="88d4531297118f595bf2fd60f6f566aec2e559393802d1f436c380f0cbbd2828";
#[tokio::test]
async fn imported_prefix_is_owned_persistent_and_rejects_forged_pixels_and_identity(){
 let root=tempfile::tempdir().unwrap();let checkpoints=root.path().join("checkpoints");directory(&checkpoints);let pixels=[70u8,90,110,255].repeat(4);let sequence=digest(&pixels.repeat(2));let runtime="b".repeat(64);let video="a".repeat(64);let cancel=CancellationToken::new();
 let expected=|ordinal|Expected{sequence_hash:&sequence,model_hash:PERSON,runtime_hash:&runtime,source_frame:&pixels,width:2,height:2,ordinal,total:2};
 for ordinal in 0..2{let path=checkpoints.join(ordinal.to_string());directory(&path);let mask=vec![0u8;512*512];file(&path.join("frame.rgba"),&pixels);file(&path.join("mask.raw"),&mask);let receipt=serde_json::json!({"schemaVersion":1,"ordinal":ordinal,"context":{"sourceHash":sequence,"frameHash":digest(&pixels),"modelHash":PERSON,"runtimeHash":runtime,"width":2,"height":2,"maskWidth":512,"maskHeight":512,"total":2},"outputHash":digest(&pixels),"maskHash":digest(&mask),"blank":true});file(&path.join("receipt.json"),&serde_json::to_vec(&receipt).unwrap());}
 let mut cache=RunCache::new(video.clone(),runtime.clone()).unwrap();let first=import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.unwrap();assert_eq!(first.metadata.frames,1);cache.insert(first).unwrap();let missing=cache.timeline().unwrap().missing_runs(&[(0.,0.1)]).unwrap();assert_eq!(missing.len(),1);assert_eq!(missing[0].start_millis,100);assert_eq!(missing[0].frames,1);
 let receipt=cache.publish(root.path(),4*1024*1024,&cancel).await.unwrap();let identity=cache.identity().unwrap();drop(cache);std::fs::remove_dir_all(&checkpoints).unwrap();let mut restored=RunCache::restore(&receipt,4*1024*1024,&cancel).await.unwrap();assert_eq!(restored.identity().unwrap(),identity);assert!(restored.automatic(0,&cancel).unwrap().is_none());drop(restored);std::fs::remove_dir_all(&receipt.directory).unwrap();
 // Recreate a completed receipt, then rehash a changed RGB byte. Matching hashes
 // cannot bypass independent original-pixel/alpha verification.
 directory(&checkpoints);let path=checkpoints.join("0");directory(&path);let mask=vec![0u8;512*512];let mut rgba=pixels.clone();rgba[0]^=1;file(&path.join("frame.rgba"),&rgba);file(&path.join("mask.raw"),&mask);let mut receipt=serde_json::json!({"schemaVersion":1,"ordinal":0,"context":{"sourceHash":sequence,"frameHash":digest(&pixels),"modelHash":PERSON,"runtimeHash":runtime,"width":2,"height":2,"maskWidth":512,"maskHeight":512,"total":2},"outputHash":digest(&rgba),"maskHash":digest(&mask),"blank":true});file(&path.join("receipt.json"),&serde_json::to_vec(&receipt).unwrap());assert!(import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.is_err());
 file(&path.join("frame.rgba"),&pixels);receipt["outputHash"]=serde_json::json!(digest(&pixels));
 for field in ["sourceHash","frameHash","modelHash","runtimeHash"]{let mut wrong=receipt.clone();wrong["context"][field]=serde_json::json!("f".repeat(64));file(&path.join("receipt.json"),&serde_json::to_vec(&wrong).unwrap());assert!(import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.is_err());}
 file(&path.join("receipt.json"),&serde_json::to_vec(&receipt).unwrap());let second=import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.unwrap();let mut cache=RunCache::new(video.clone(),runtime.clone()).unwrap();cache.insert(second).unwrap();assert!(cache.insert(import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.unwrap()).is_err());
 std::fs::rename(path.join("receipt.json"),path.join("receipt.pending")).unwrap();assert!(import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&cancel,std::time::Duration::from_secs(10)).await.is_err());
 let stopped=CancellationToken::new();stopped.cancel();assert!(import_checkpoint(&checkpoints,expected(0),&video,0,root.path(),&stopped,std::time::Duration::from_secs(10)).await.is_err());drop(cache);assert!(std::fs::read_dir(root.path()).unwrap().all(|entry|entry.unwrap().path()==checkpoints));
}
#[tokio::test]
#[ignore="requires actual pinned models and the native checkpoint-enabled executable"]
async fn actual_native_frames_import_for_all_three_models_and_outlive_native_files(){
 let root=tempfile::tempdir().unwrap();let source=[50u8,90,130,210].repeat(4);let pixels=source.repeat(2);let sequence=digest(&pixels);let video="a".repeat(64);let cancel=CancellationToken::new();let executable=std::env::var("VIDEO_KADR_TEST_ENHANCE_BIN").unwrap();let library:PathBuf=std::env::var("VIDEO_KADR_TEST_CHATTERBOX_LIBRARY").unwrap().into();let runtime=digest(&std::fs::read(&library).unwrap());
 for(name,family,variable,model_hash)in [("person",None,"VIDEO_KADR_TEST_PERSON_MODEL",PERSON),("selfie",Some("selfie"),"VIDEO_KADR_TEST_SELFIE_MODEL","3241ac4ad8aa35bdaf33946776db29f7c283a413aa0b0dacb9483594b4531aad"),("object",Some("object"),"VIDEO_KADR_TEST_OBJECT_MODEL","60920e99c45464f2ba57bee2ad08c919a52bbf852739e96947fbb4358c0d964a")]{
  let directory_path=root.path().join(name);directory(&directory_path);let checkpoints=directory_path.join("checkpoints");directory(&checkpoints);let input=directory_path.join("input.rgba");file(&input,&pixels);let mut request=serde_json::json!({"schemaVersion":if family.is_none(){7}else{10},"model":std::env::var(variable).unwrap(),"runtimeLibrary":library,"input":input,"output":directory_path.join("output.rgba"),"maskOutput":directory_path.join("masks.raw"),"checkpointOutput":checkpoints,"sourceSha256":sequence,"width":2,"height":2,"frames":2});if let Some(family)=family{request["family"]=serde_json::json!(family);}let path=directory_path.join("request.json");file(&path,&serde_json::to_vec(&request).unwrap());let result=std::process::Command::new(&executable).arg(if family.is_none(){"--person-sequence"}else{"--cutout-sequence"}).arg(path).output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));
  let mut cache=RunCache::new_for_model(video.clone(),runtime.clone(),model_hash.into()).unwrap();for ordinal in 0..2{let expected=Expected{sequence_hash:&sequence,model_hash,runtime_hash:&runtime,source_frame:&source,width:2,height:2,ordinal,total:2};cache.insert(import_checkpoint(&checkpoints,expected,&video,5000,root.path(),&cancel,std::time::Duration::from_secs(20)).await.unwrap()).unwrap();}
  assert!(cache.timeline().unwrap().missing_runs(&[(5.,5.1)]).unwrap().is_empty());let identity=cache.identity().unwrap();let receipt=cache.publish(root.path(),8*1024*1024,&cancel).await.unwrap();drop(cache);std::fs::remove_dir_all(directory_path).unwrap();let mut restored=RunCache::restore(&receipt,8*1024*1024,&cancel).await.unwrap();assert_eq!(restored.identity().unwrap(),identity);let _=restored.automatic(5000,&cancel).unwrap();let _=restored.automatic(5100,&cancel).unwrap();drop(restored);std::fs::remove_dir_all(receipt.directory).unwrap();
 }
 assert_eq!(std::fs::read_dir(root.path()).unwrap().count(),0);
}
